// === Tab: vert.glsl ===
   attribute vec3 aPosition;
   attribute vec2 aTexCoord;
   uniform mat4 uProjectionMatrix;
   uniform mat4 uModelViewMatrix;
   varying vec2 vTexCoord;

   void main() {
     vTexCoord = aTexCoord;
     vec4 position = vec4(aPosition, 1.0);
     gl_Position = uProjectionMatrix * uModelViewMatrix * position;
   }

// === Tab: frag.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform vec2 u_mouse;
uniform sampler2D canvas;
uniform sampler2D imgTex;

vec3 rand3(vec3 p)
{
	vec3 q = vec3(
		dot(p, vec3(127.1, 311.7, 74.7)),
		dot(p, vec3(269.5, 183.3, 246.1)),
		dot(p, vec3(113.5, 271.9, 124.6))
		);

	return fract(sin(q) * 43758.5453123);
}

void main() {
	vec3 col = vec3(0.);
	vec2 uv = 1.1 * .5 * gl_FragCoord.xy / u_resolution.xy;
	vec2 mouse = u_mouse / u_resolution.xy;
	mouse = (mouse-.5) * 2.;

	float shrink_factor = 1.05;
	vec2 s_uv = uv * shrink_factor - (shrink_factor - 1.) / 2.;

	s_uv += mouse * vec2(0.03, 0.1);

	vec3 prev = texture2D(canvas, vec2(s_uv.x, 1. - s_uv.y)).rgb;
	vec3 now = vec3(0.);

	float s = sin(u_time);
	s += 1.; 
	s *= .5;
	s = s * .5 + .25; 
	float dot = rand3( vec3(floor(uv*500.), u_time) ).r;
	dot = step(dot, s);
	now = vec3(dot);

	float circle_radius = 0.4;
	float circle_border_width = 0.01;
	float prev_mask = step(length(s_uv-.5), circle_radius-circle_border_width);
	float now_mask  = step(length(s_uv-.5), circle_radius);

	now *= now_mask;

	col = mix(now, prev, prev_mask);

	gl_FragColor = vec4(col, 1.0);
}

